import { History } from './history'
import { clampParam, DEFAULT_PARAMS, type ParamKey, type Params } from './params'
import { Rng } from './rng'
import type { World } from './types'
import { createWorld, DT, step } from './world'

/** Steps per real second at speed 1. */
const REALTIME_STEPS = 1 / DT

/**
 * Owns the world, its RNG stream and the recorded history.
 * Rendering reads `world` directly; React subscribes for the UI numbers.
 */
export class Engine {
  params: Params
  world: World
  history = new History()
  running = false
  speed = 1
  /** Bumped whenever observers should re-read. */
  version = 0
  selectedId: number | null = null

  private rng: Rng
  private accumulator = 0
  private listeners = new Set<() => void>()

  constructor(params: Params = DEFAULT_PARAMS) {
    this.params = { ...params }
    this.world = createWorld(this.params)
    this.rng = new Rng((this.params.seed ^ 0x9e3779b9) >>> 0)
    this.history.maybeSample(this.world)
  }

  subscribe = (fn: () => void) => {
    this.listeners.add(fn)
    return () => this.listeners.delete(fn)
  }

  getSnapshot = () => this.version

  notify() {
    this.version++
    for (const fn of this.listeners) fn()
  }

  reset(params: Params = this.params) {
    this.params = { ...params }
    this.world = createWorld(this.params)
    this.rng = new Rng((this.params.seed ^ 0x9e3779b9) >>> 0)
    this.history.reset()
    this.history.maybeSample(this.world)
    this.accumulator = 0
    this.selectedId = null
    this.notify()
  }

  setParam(key: ParamKey, value: number) {
    this.params = { ...this.params, [key]: clampParam(key, value) }
    this.notify()
  }

  setParams(params: Params) {
    this.params = { ...params }
    this.notify()
  }

  setRunning(running: boolean) {
    this.running = running
    this.accumulator = 0
    this.notify()
  }

  setSpeed(speed: number) {
    this.speed = speed
    this.notify()
  }

  select(id: number | null) {
    this.selectedId = id
    this.notify()
  }

  selected() {
    if (this.selectedId === null) return null
    return this.world.blobs.find((b) => b.id === this.selectedId) ?? null
  }

  /** One fixed step, regardless of run state. */
  stepOnce() {
    step(this.world, this.params, this.rng)
    this.history.maybeSample(this.world)
    this.accumulator = 0
    this.notify()
  }

  /**
   * Advance by wall-clock time. Returns the leftover fraction of a step,
   * which the renderer uses to interpolate positions.
   */
  advance(realSeconds: number): number {
    if (!this.running) return 0
    const budget = Math.min(realSeconds, 0.25) * this.speed * REALTIME_STEPS
    this.accumulator += budget
    let steps = Math.floor(this.accumulator)
    // Cap work per frame so a slow frame cannot spiral.
    const maxSteps = Math.ceil(24 * Math.max(1, this.speed))
    if (steps > maxSteps) {
      steps = maxSteps
      this.accumulator = 0
    } else {
      this.accumulator -= steps
    }
    for (let i = 0; i < steps; i++) {
      step(this.world, this.params, this.rng)
      this.history.maybeSample(this.world)
    }
    return this.accumulator
  }

  /** Headless fast-forward, used by tests and the tuner. */
  run(seconds: number) {
    const steps = Math.round(seconds / DT)
    for (let i = 0; i < steps; i++) {
      step(this.world, this.params, this.rng)
      this.history.maybeSample(this.world)
    }
  }
}

