import { movingAverage, findPeaks, mean, bestLag } from '../src/sim/analysis'
import { DEFAULT_PARAMS, PRESETS, type ParamKey, type Params } from '../src/sim/params'
import { CONST, overrideConst } from '../src/sim/world'

type Report = {
  label: string
