  ]
  for (const lobe of lobes) {
    ctx.beginPath()
    ctx.ellipse(top.sx + lobe.dx * s + leanX, top.sy + lobe.dy * s, lobe.r * s, lobe.r * s * 0.92, 0, 0, TAU)
    ctx.fillStyle = lobe.tone
