  const fruitColor = seriesColor('fruit', opts.mode)
  const hung = tree.anchors
    .map((a, i) => ({ a, i, p: project(cam, tree.x + a.x, tree.y + a.y, a.z * tree.scale) }))
    .sort((l, r) => l.p.depth - r.p.depth)
