            <span className="stat-value">{world.counts.red}</span>
          </span>
        </div>
      </header>

      <main className="layout">
        <section className="stage">
          <Garden engine={engine} mode={mode} version={version} onPick={onPick} />
          <p className="stage-hint">Drag to turn the garden · click a blob to inspect it</p>
        </section>

        <aside className="side">
          <Inspector blob={selected} params={params} mode={mode} time={world.t} onClose={() => engine.select(null)} />
          <Controls
            params={params}
            running={engine.running}
            speed={engine.speed}
            activePreset={activePreset}
            onParam={onParam}
            onPreset={onPreset}
            onPlay={() => engine.setRunning(!engine.running)}
            onStep={() => engine.stepOnce()}
            onReset={() => engine.reset()}
            onRandomize={onRandomize}
            onSpeed={(v) => engine.setSpeed(v)}
          />
        </aside>

        <section className="story">
          <ChartsPanel
            samples={engine.history.samples}
            mode={mode}
            fruitCapacity={fruitCapacity}
            blueAlive={world.counts.blue}
            redAlive={world.counts.red}
          />
        </section>
      </main>
    </div>
  )
}

input.content:
:root {
  --surface: #fcfcfb;
  --surface-2: #f4f2ec;
  --surface-3: #eae7de;
  --ink: #1d1c19;
  --ink-2: #4d4a43;
  --ink-3: #7c776c;
  --line: #dedad0;
  --grid: #e6e2d8;
  --radius: 12px;
  --shadow: 0 1px 2px rgba(30, 27, 20, 0.06), 0 6px 18px rgba(30, 27, 20, 0.06);
  color-scheme: light dark;
}

.app[data-mode='dark'] {
  --surface: #1a1a19;
  --surface-2: #222220;
  --surface-3: #2b2b28;
  --ink: #f0eee9;
  --ink-2: #b9b5ac;
  --ink-3: #8b877e;
  --line: #34342f;
  --grid: #2f2f2b;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.4), 0 6px 20px rgba(0, 0, 0, 0.35);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

.app {
  min-height: 100vh;
  background: var(--surface-2);
  color: var(--ink);
  font: 14px/1.5 ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

/* --- top bar --------------------------------------------------------- */

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding: 14px 20px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
  position: sticky;
  top: 0;
  z-index: 5;
}

.topbar h1 {
  margin: 0;
  font-size: 19px;
  letter-spacing: -0.01em;
}

.readout {
  display: flex;
  gap: 18px;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  line-height: 1.2;
}

.stat-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ink-3);
}

.stat-value {
  font-size: 17px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.stat-fruit .stat-value {
  color: #00947a;
}
.stat-blue .stat-value {
  color: #3f6bd8;
}
.stat-red .stat-value {
  color: #d64533;
}
.app[data-mode='dark'] .stat-fruit .stat-value {
  color: #23ab92;
}
.app[data-mode='dark'] .stat-blue .stat-value {
  color: #6285dd;
}
.app[data-mode='dark'] .stat-red .stat-value {
  color: #e05a4e;
}

/* --- layout ---------------------------------------------------------- */

.layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  grid-template-areas:
    'stage side'
    'story side';
  gap: 16px;
  padding: 16px;
  align-items: start;
}

.stage {
  grid-area: stage;
}
.side {
  grid-area: side;
}
.story {
  grid-area: story;
}

@media (max-width: 1080px) {
  .layout {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas: 'stage' 'side' 'story';
  }
}

.stage {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 8px 8px 4px;
  overflow: hidden;
}

.garden-canvas {
  display: block;
  width: 100%;
  height: min(58vh, 520px);
  touch-action: none;
  cursor: grab;
  border-radius: 8px;
}

.garden-canvas:active {
  cursor: grabbing;
}

.stage-hint {
  margin: 4px 0 6px;
  text-align: center;
  font-size: 12px;
  color: var(--ink-3);
}

/* --- panels ---------------------------------------------------------- */

.panel {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 14px;
}

.panel + .panel,
.charts > * + * {
  margin-top: 12px;
}

.panel-title {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
  margin: 0 0 10px;
  font-size: 13px;
  font-weight: 650;
  letter-spacing: 0.01em;
}

.panel-caption {
  font-weight: 400;
  font-size: 12px;
  color: var(--ink-3);
}

.panel-pair {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 12px;
}

.muted {
  color: var(--ink-3);
  margin: 0;
}

.note {
  margin: 8px 0 0;
  font-size: 12px;
  color: var(--ink-3);
}

/* --- controls -------------------------------------------------------- */

.button-row,
.speed-row {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.speed-row {
  margin-top: 10px;
  align-items: center;
}

.speed-label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ink-3);
  margin-right: 2px;
}

button {
  font: inherit;
  color: var(--ink);
  background: var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 6px 10px;
  cursor: pointer;
}

button:hover:not(:disabled) {
  background: var(--surface-3);
}

button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

button.primary {
  background: var(--ink);
  color: var(--surface);
  border-color: var(--ink);
  font-weight: 600;
  min-width: 88px;
}

.chip {
  padding: 3px 9px;
  font-size: 12px;
  border-radius: 999px;
}

.chip-on {
  background: var(--ink);
  color: var(--surface);
  border-color: var(--ink);
}

.ghost {
  background: transparent;
  border-color: transparent;
}

.close {
  margin-left: auto;
  padding: 2px 6px;
  color: var(--ink-3);
}

.link {
  background: none;
  border: none;
  padding: 0;
  color: var(--ink);
  text-decoration: underline;
  cursor: pointer;
  font-size: inherit;
}

.preset-list {
  display: grid;
  gap: 6px;
}

.preset {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1px;
  text-align: left;
  padding: 7px 10px;
}

.preset-name {
  font-weight: 600;
  font-size: 13px;
}

.preset-blurb {
  font-size: 11.5px;
  color: var(--ink-3);
}

.preset-on {
  border-color: var(--ink);
  background: var(--surface-3);
}

.preset-on .preset-blurb {
  color: var(--ink-2);
}

.slider-list {
  display: grid;
  gap: 12px;
}

.slider {
  display: grid;
  gap: 3px;
}

.slider-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}

.slider-label {
  font-size: 12.5px;
  font-weight: 550;
  display: flex;
  align-items: center;
  gap: 6px;
}

.badge {
  font-size: 9.5px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--ink-3);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 0 4px;
}

.slider-value {
  font-size: 12.5px;
  font-variant-numeric: tabular-nums;
  color: var(--ink-2);
}

.slider-hint {
  font-size: 11px;
  color: var(--ink-3);
}

input[type='range'] {
  width: 100%;
  accent-color: var(--ink);
}

/* --- inspector ------------------------------------------------------- */

.dot,
.swatch {
  width: 9px;
  height: 9px;
  border-radius: 3px;
  display: inline-block;
  flex: none;
}

.energy-bar {
  position: relative;
  height: 8px;
  border-radius: 999px;
  background: var(--surface-3);
  overflow: hidden;
  margin-bottom: 10px;
}

.energy-fill {
  height: 100%;
  border-radius: 999px;
}

.energy-mark {
  position: absolute;
  top: -2px;
  width: 2px;
  height: 12px;
  background: var(--ink-3);
}

.insp-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px 14px;
}

.insp-row {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
  padding: 2px 0;
  border-bottom: 1px solid var(--grid);
}

.insp-label {
  color: var(--ink-3);
}

.insp-value {
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.traits {
  margin-top: 12px;
}

.traits-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ink-3);
}

.trait-bar-row {
  display: grid;
  grid-template-columns: 46px 1fr 34px;
  align-items: center;
  gap: 8px;
  margin-top: 5px;
  font-size: 11.5px;
}

.trait-bar-label {
  color: var(--ink-3);
  text-transform: capitalize;
}

.trait-bar {
  position: relative;
  height: 6px;
  background: var(--surface-3);
  border-radius: 999px;
}

.trait-bar-base {
  position: absolute;
  left: 38.5%;
  top: -2px;
  width: 1px;
  height: 10px;
  background: var(--ink-3);
}

.trait-bar-fill {
  position: absolute;
  top: 0;
  height: 100%;
  border-radius: 999px;
  min-width: 2px;
}

.trait-bar-value {
  font-variant-numeric: tabular-nums;
  text-align: right;
  color: var(--ink-2);
}

/* --- charts ---------------------------------------------------------- */

.chart {
  position: relative;
}

.chart svg {
  display: block;
  overflow: visible;
}

.grid {
  stroke: var(--grid);
  stroke-width: 1;
}

.axis {
  fill: var(--ink-3);
  font-size: 10.5px;
  font-variant-numeric: tabular-nums;
}

.axis-title {
  font-size: 10px;
  font-variant-numeric: normal;
}

.series-label {
  font-size: 11px;
  font-weight: 600;
}

.crosshair {
  stroke: var(--ink-3);
  stroke-width: 1;
  stroke-dasharray: 3 3;
}

.legend {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  margin-bottom: 6px;
  font-size: 11.5px;
  color: var(--ink-2);
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.view-toggle {
  margin-left: auto;
  display: flex;
  gap: 4px;
}

.tooltip {
  position: absolute;
  top: 4px;
  transform: translateX(-50%);
  pointer-events: none;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: var(--shadow);
  padding: 6px 8px;
  font-size: 11.5px;
  min-width: 128px;
}

.tooltip-time {
  color: var(--ink-3);
  margin-bottom: 3px;
  font-variant-numeric: tabular-nums;
}

.tooltip-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.tooltip-name {
  color: var(--ink-2);
}

.tooltip-value {
  margin-left: auto;
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}

.headline {
  margin: 0 0 6px;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.35;
}

.notes {
  margin: 0;
  padding-left: 18px;
  color: var(--ink-2);
  font-size: 12.5px;
}

.notes li + li {
  margin-top: 2px;
}

.trait-grid {
  display: grid;
  gap: 8px;
}

.trait-head {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.trait-label {
  font-size: 12px;
  font-weight: 600;
}

.trait-hint {
  font-size: 10.5px;
  color: var(--ink-3);
}

.table-wrap {
  max-height: 260px;
  overflow: auto;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}

.data-table th,
.data-table td {
  text-align: right;
  padding: 3px 8px;
  border-bottom: 1px solid var(--grid);
}

.data-table th {
  position: sticky;
  top: 0;
  background: var(--surface);
  color: var(--ink-3);
  font-weight: 550;
  white-space: nowrap;
}

.data-table th:first-child,
.data-table td:first-child {
  text-align: left;
}

.data-table th .swatch {
  margin-right: 5px;
}

