  const valsB = listB.split(',').map(Number)
  const base = presetFilter ? (PRESETS.find((p) => p.id === presetFilter)?.params ?? DEFAULT_PARAMS) : DEFAULT_PARAMS
  console.log(`  rows: ${keyA}   cols: ${keyB}   cell: coexist/${seedCount} (mean blue/red)\n`)

