        redSum += r.redMean
      }
      cells.push(`${ok}/${seedCount} ${(blueSum / seedCount).toFixed(0)}b ${(redSum / seedCount).toFixed(0)}r`.padStart(18))
    }
    console.log(String(va).padEnd(12) + cells.join(''))
  }
}

