    }
    console.log(String(va).padEnd(12) + cells.join(''))
  }
}

console.log(`\n  probe · ${seconds}s per run · ${seeds} seed(s)\n`)

const scan = arg('scan')
const scan2 = arg('scan2')
if (scan && scan2) {
  runScan(scan, scan2, seeds, seconds)
