  const n = parseInt(hex.slice(1), 16)
  const r = (n >> 16) & 255
  const g = (n >> 8) & 255
  const b = n & 255
  const mix = (c: number) => Math.round(amount < 0 ? c * (1 + amount) : c + (255 - c) * amount)
  return `rgb(${mix(r)}, ${mix(g)}, ${mix(b)})`
}

export function fitCamera(cam: Camera, width: number, height: number, radius: number) {
  const margin = 26
  const usable = Math.min(width - margin * 2, (height - margin * 2) / (cam.tilt + 0.34))
  cam.scale = usable / (radius * 2)
  cam.cx = width / 2
  cam.cy = height / 2 - radius * cam.scale * 0.12
}

