// Minimal CDP driver: click Play, let the garden run, screenshot the panels.
// Usage: node drive.mjs <outDir> <runSeconds> [dark|light]
import { writeFileSync } from 'node:fs'

const [outDir, runSecondsRaw, scheme = 'light'] = process.argv.slice(2)
const runSeconds = Number(runSecondsRaw ?? 30)

const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json()
const page = targets.find((t) => t.type === 'page')
if (!page) throw new Error('no page target')

const ws = new WebSocket(page.webSocketDebuggerUrl)
await new Promise((r) => ws.addEventListener('open', r, { once: true }))

let nextId = 1
const pending = new Map()
ws.addEventListener('message', (ev) => {
  const msg = JSON.parse(ev.data)
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id)
    pending.delete(msg.id)
    msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result)
  }
})
const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const id = nextId++
    pending.set(id, { resolve, reject })
    ws.send(JSON.stringify({ id, method, params }))
  })

const evaluate = async (expression) => {
  const r = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
  if (r.exceptionDetails) throw new Error(r.exceptionDetails.exception?.description ?? 'eval failed')
  return r.result.value
}
const shot = async (name) => {
  const r = await send('Page.captureScreenshot', { format: 'png' })
  writeFileSync(`${outDir}/${name}.png`, Buffer.from(r.data, 'base64'))
  console.log(`shot ${name}`)
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

await send('Page.enable')
await send('Runtime.enable')
await send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-color-scheme', value: scheme }] })
await send('Page.navigate', { url: 'http://localhost:9217/' })
await sleep(1500)

// Console errors are the thing a screenshot cannot show.
const errors = []
ws.addEventListener('message', (ev) => {
  const m = JSON.parse(ev.data)
  if (m.method === 'Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.text)
  if (m.method === 'Runtime.consoleAPICalled' && m.params.type === 'error')
    errors.push(m.params.args.map((a) => a.value ?? a.description).join(' '))
})

const clickText = (label) =>
  evaluate(`(() => {
    const el = [...document.querySelectorAll('button')].find((b) => b.textContent.trim().startsWith(${JSON.stringify(label)}))
    if (!el) return 'missing: ' + ${JSON.stringify(label)}
    el.click()
    return 'ok'
  })()`)

console.log('play:', await clickText('Play'))
console.log('speed:', await clickText('8x'))
await sleep(runSeconds * 1000)

console.log('state:', JSON.stringify(await evaluate(`document.querySelector('.topbar-stats')?.innerText.replace(/\\n/g, ' ')`)))
await shot('01-garden')

// Inspector: click the middle of the canvas repeatedly until a blob is picked.
await evaluate(`(() => {
  const c = document.querySelector('canvas')
  const r = c.getBoundingClientRect()
  for (let i = 0; i < 400; i++) {
    const x = r.left + r.width * (0.5 + 0.42 * Math.cos(i))
    const y = r.top + r.height * (0.5 + 0.34 * Math.sin(i * 1.7))
    c.dispatchEvent(new PointerEvent('pointerdown', { clientX: x, clientY: y, bubbles: true }))
    c.dispatchEvent(new PointerEvent('pointerup', { clientX: x, clientY: y, bubbles: true }))
    if (document.querySelector('.inspector-rows, .inspect-row, .trait-bar')) return 'picked at ' + i
  }
  return 'no blob picked'
})()`).then((r) => console.log('inspect:', r))
await sleep(400)
await shot('02-inspector')

await evaluate(`document.querySelector('.story')?.scrollIntoView({ block: 'start' }); window.scrollBy(0, 0)`)
await sleep(600)
await shot('03-charts')

await evaluate(`window.scrollTo(0, document.body.scrollHeight)`)
await sleep(600)
await shot('04-bottom')

console.log('errors:', errors.length ? errors : 'none')
ws.close()

