import { useMemo } from 'react'
import type { Sample } from '../../sim/history'
import { seriesColor, type Mode } from '../../theme'

type Props = { samples: Sample[]; mode: Mode; height?: number }

const PAD = { top: 12, right: 14, bottom: 30, left: 40 }

/**
 * Blue against red, with time as the path rather than an axis. Loops here mean
 * the two groups are chasing each other round; a drift into a corner means the
 * garden is settling.
 */
export function PhasePlot({ samples, mode, height = 200 }: Props) {
  const w = 320
  const h = height
  const innerW = w - PAD.left - PAD.right
  const innerH = h - PAD.top - PAD.bottom

  const { path, dots, maxB, maxR } = useMemo(() => {
    const maxB = Math.max(1, ...samples.map((s) => s.blue))
    const maxR = Math.max(1, ...samples.map((s) => s.red))
    const px = (v: number) => PAD.left + (v / maxB) * innerW
    const py = (v: number) => PAD.top + innerH - (v / maxR) * innerH
    let path = ''
    for (let i = 0; i < samples.length; i++) {
      path += `${i ? 'L' : 'M'}${px(samples[i].blue).toFixed(1)} ${py(samples[i].red).toFixed(1)}`
    }
    const last = samples[samples.length - 1]
    const dots = last ? [{ x: px(last.blue), y: py(last.red) }] : []
    return { path, dots, maxB, maxR }
  }, [samples, innerW, innerH])

  const blue = seriesColor('blue', mode)
  const red = seriesColor('red', mode)

  return (
    <svg width="100%" height={h} viewBox={`0 0 ${w} ${h}`} role="img" aria-label="Blue population against red population">
      <line className="grid" x1={PAD.left} x2={PAD.left + innerW} y1={PAD.top + innerH} y2={PAD.top + innerH} />
      <line className="grid" x1={PAD.left} x2={PAD.left} y1={PAD.top} y2={PAD.top + innerH} />
      <text className="axis" x={PAD.left} y={h - 16} textAnchor="start">
        0
      </text>
      <text className="axis" x={PAD.left + innerW} y={h - 16} textAnchor="end">
        {Math.round(maxB)}
      </text>
      <text className="axis axis-title" x={PAD.left + innerW / 2} y={h - 4} textAnchor="middle" fill={blue}>
        Blue →
      </text>
      <text className="axis" x={PAD.left - 6} y={PAD.top + 6} textAnchor="end">
        {Math.round(maxR)}
      </text>
      <text
        className="axis axis-title"
        x={12}
        y={PAD.top + innerH / 2}
        textAnchor="middle"
        fill={red}
        transform={`rotate(-90 12 ${PAD.top + innerH / 2})`}
      >
        Red →
      </text>
      <path d={path} fill="none" stroke={blue} strokeOpacity={0.28} strokeWidth={1.5} strokeLinejoin="round" />
      {dots.map((d, i) => (
        <circle key={i} cx={d.x} cy={d.y} r={5} fill={red} stroke="var(--surface)" strokeWidth={2} />
      ))}
    </svg>
  )
}

import { useMemo, useState } from 'react'
import type { Sample } from '../sim/history'
import { summarise } from '../sim/analysis'
import { TimelineChart, type Series } from './charts/TimelineChart'
import { PhasePlot } from './charts/PhasePlot'
import { TraitChart } from './charts/TraitChart'
import { seriesColor, SERIES_LABEL, type Mode, type SeriesKey } from '../theme'

type Props = {
  samples: Sample[]
  mode: Mode
  fruitCapacity: number
  blueAlive: number
  redAlive: number
}

type View = 'chart' | 'table'

const KEYS: SeriesKey[] = ['fruit', 'blue', 'red']

function Legend({ mode, keys = KEYS }: { mode: Mode; keys?: SeriesKey[] }) {
  return (
    <div className="legend">
      {keys.map((k) => (
        <span key={k} className="legend-item">
          <span className="swatch" style={{ background: seriesColor(k, mode) }} />
          {SERIES_LABEL[k]}
        </span>
      ))}
    </div>
  )
}

function Table({ samples, mode }: { samples: Sample[]; mode: Mode }) {
  // Thin to a readable number of rows — the chart is the detailed view.
  const stride = Math.max(1, Math.ceil(samples.length / 40))
  const rows = samples.filter((_, i) => i % stride === 0)
  return (
    <div className="table-wrap">
      <table className="data-table">
        <thead>
          <tr>
            <th scope="col">Time</th>
            {KEYS.map((k) => (
              <th key={k} scope="col">
                <span className="swatch" style={{ background: seriesColor(k, mode) }} />
                {SERIES_LABEL[k]}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((s) => (
            <tr key={s.t}>
              <td>{s.t.toFixed(0)}s</td>
              <td>{s.fruit}</td>
              <td>{s.blue}</td>
              <td>{s.red}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

export function ChartsPanel({ samples, mode, fruitCapacity, blueAlive, redAlive }: Props) {
  const [view, setView] = useState<View>('chart')
  const [indexed, setIndexed] = useState(false)

  const series: Series[] = useMemo(
    () => [
      { key: 'fruit', values: samples.map((s) => s.fruit) },
      { key: 'blue', values: samples.map((s) => s.blue) },
      { key: 'red', values: samples.map((s) => s.red) },
    ],
    [samples],
  )

  const summary = useMemo(
    () => summarise({ samples, fruitCapacity, blueAlive, redAlive }),
    [samples, fruitCapacity, blueAlive, redAlive],
  )

  // When one series dwarfs the others the raw counts stop being readable, so
  // point at the indexed view rather than silently rescaling behind the user.
  const spread = useMemo(() => {
    const peaks = series.map((s) => Math.max(1, ...s.values))
    return Math.max(...peaks) / Math.max(1, Math.min(...peaks))
  }, [series])

  return (
    <div className="charts">
      <div className="panel">
        <h3 className="panel-title">
          Populations over time
          <span className="view-toggle">
            <button className={`chip ${!indexed ? 'chip-on' : ''}`} onClick={() => setIndexed(false)}>
              Counts
            </button>
            <button className={`chip ${indexed ? 'chip-on' : ''}`} onClick={() => setIndexed(true)}>
              Share of peak
            </button>
            <button className={`chip ${view === 'table' ? 'chip-on' : ''}`} onClick={() => setView(view === 'table' ? 'chart' : 'table')}>
              Table
            </button>
          </span>
        </h3>
        <Legend mode={mode} />
        {view === 'chart' ? (
          <TimelineChart
            samples={samples}
            series={series}
            mode={mode}
            indexed={indexed}
            yLabel={indexed ? 'Share of each groups own peak' : 'Count'}
          />
        ) : (
          <Table samples={samples} mode={mode} />
        )}
        {!indexed && spread > 6 && view === 'chart' && (
          <p className="note">
            Fruit and the blob groups are on very different scales right now. <button className="link" onClick={() => setIndexed(true)}>Share of peak</button> puts
            them side by side.
          </p>
        )}
      </div>

      <div className="panel">
        <h3 className="panel-title">What happened</h3>
        <p className={`headline tone-${summary.tone}`}>{summary.headline}</p>
        <ul className="notes">
          {summary.notes.map((n) => (
            <li key={n}>{n}</li>
          ))}
        </ul>
      </div>

      <div className="panel-pair">
        <div className="panel">
          <h3 className="panel-title">
            Blue against red
            <span className="panel-caption">loops mean the two are chasing each other</span>
          </h3>
          <PhasePlot samples={samples} mode={mode} />
        </div>
        <div className="panel">
          <h3 className="panel-title">
            Inherited traits
            <span className="panel-caption">average of each group, 1.0 is the starting stock</span>
          </h3>
          <TraitChart samples={samples} mode={mode} />
          <Legend mode={mode} keys={['blue', 'red']} />
        </div>
      </div>
    </div>
  )
}

import type { Kind, World } from './types'
import { meanEnergy, meanTrait } from './world'

export type Sample = {
  t: number
  fruit: number
  blue: number
  red: number
  blueEnergy: number
  redEnergy: number
  blueSpeed: number
  redSpeed: number
  blueVision: number
  redVision: number
  blueThrift: number
  redThrift: number
}

const MAX_SAMPLES = 1400
const BASE_INTERVAL = 0.5

/**
 * Rolling record of the run. When it fills up it halves its own resolution
 * instead of dropping the start, so the whole run stays on one timeline.
 */
export class History {
  samples: Sample[] = []
  interval = BASE_INTERVAL
  private nextAt = 0

  reset() {
    this.samples = []
    this.interval = BASE_INTERVAL
    this.nextAt = 0
  }

  maybeSample(world: World) {
    if (world.t < this.nextAt) return
    this.nextAt = world.t + this.interval
    this.samples.push(snapshot(world))
    if (this.samples.length > MAX_SAMPLES) {
      this.samples = this.samples.filter((_, i) => i % 2 === 0)
      this.interval *= 2
    }
  }

  last(): Sample | undefined {
    return this.samples[this.samples.length - 1]
  }
}

function snapshot(world: World): Sample {
  return {
    t: world.t,
    fruit: world.counts.fruit,
    blue: world.counts.blue,
    red: world.counts.red,
    blueEnergy: meanEnergy(world, 'blue'),
    redEnergy: meanEnergy(world, 'red'),
    blueSpeed: meanTrait(world, 'blue', 'speed'),
    redSpeed: meanTrait(world, 'red', 'speed'),
    blueVision: meanTrait(world, 'blue', 'vision'),
    redVision: meanTrait(world, 'red', 'vision'),
    blueThrift: meanTrait(world, 'blue', 'thrift'),
    redThrift: meanTrait(world, 'red', 'thrift'),
  }
}

export function seriesOf(samples: Sample[], key: keyof Sample): number[] {
  return samples.map((s) => s[key])
}

export function kindKey(kind: Kind): 'blue' | 'red' {
  return kind
}

import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react'
